#!/usr/bin/env bash
# Boot a DSH profile with the local plugin, without installing it into the
# profile. Use this while developing; use the Git/npm address for a real install.
#
#   ./scripts/dsh-dev.sh              # tui profile
#   DSH_PROFILE=web ./scripts/dsh-dev.sh --no-open --port 0
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
PROFILE="${DSH_PROFILE:-tui}"
PATCH="$ROOT/.local/dsh-minemate.patch.yml"

bash "$ROOT/scripts/link-harness-peers.sh"
mkdir -p "$ROOT/.local"

cat >"$PATCH" <<YAML
# Generated by scripts/dsh-dev.sh — do not commit.
- insert:
    - id: dsh-minemate
      name: '$ROOT/index.js'
      config:
        host: 127.0.0.1
        port: 25565
        username: Alex
        auth: offline
        version: '1.21.6'
        owner: FPS1024
        companionName: Alex
        autoConnect: true
        reconnect: true
        reflex: true
        humanize: true
        humanizeChat: true
        reactionDelayMs: 150
        gaze: true
        gait: true
        autoDefend: true
        avoidLava: true
        autoSleep: true
        autonomy: 0
        proactiveIntervalMs: 180000
        ambientChat: false
        agentSessionId: ''
YAML

echo "[dsh-minemate] profile=$PROFILE patch=$PATCH"
exec dsh "$PROFILE" --patch "$PATCH" "$@"
